    /// Serves a `Server` on a connection (pass it in `CapSlot.export`).
    /// Inherited interfaces dispatch here too (the Server protocol inherits
    /// their requirements; E-order holds for the whole closure).
    public struct Export: ExportHandler {
        public let server: any Server
        public init(_ server: any Server) { self.server = server }
        public func handle(_ call: InboundCall, on connection: isolated RPCConnection) async throws -> CallResponse {
            switch call.interfaceID {
            case InventoryService.interfaceID:
                switch call.methodID {
                case InventoryService.Method.getInventory.rawValue:
                    let params = try decoding { try InventoryService.GetInventoryParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.getInventory(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case InventoryService.Method.addItem.rawValue:
                    let params = try decoding { try InventoryService.AddItemParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.addItem(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case InventoryService.Method.removeItem.rawValue:
                    let params = try decoding { try InventoryService.RemoveItemParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.removeItem(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case InventoryService.Method.startTrade.rawValue:
                    let params = try decoding { try InventoryService.StartTradeParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.startTrade(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case InventoryService.Method.filterByRarity.rawValue:
                    let params = try decoding { try InventoryService.FilterByRarityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.filterByRarity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                default:
                    throw RPCError.unimplemented(reason: "InventoryService: no such method")
                }
            default:
                throw RPCError.unimplemented(reason: "InventoryService: wrong interface")
            }
        }
    }

}

